try:
    print('>>> f = filter')
    print('>>> x = True')
    print('>>> y = 3')
    print('>>> f(x, y)')
    f = filter
    x = True
    y = 3
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
